use super::ThinkingMessage;
    use crate::agent::token_estimation::TokenEstimator;
    use crate::tui::thinking_display::ThinkingDisplay;
    use crate::tui::theme::Theme;
    use ratatui::buffer::Buffer;
    use ratatui::layout::Rect;

    fn theme() -> Theme {
        Theme::gh_dark()
    }

    #[test]
    fn collapsed_header_uses_calibrated_token_estimate() {
        // L-4: the token count in the collapsed header must come from the
        // calibrated TokenEstimator, not a word count.
        let reasoning = "a b c d e f g h".to_string(); // 8 words, 15 chars
        let msg = ThinkingMessage { reasoning: reasoning.clone() };
        let est = TokenEstimator::heuristic(); // 4.0 chars/token → 15/4 = 4 tokens
        let expected = est.estimate_tokens(&reasoning);
        assert_eq!(expected, 4, "sanity: heuristic estimate for 15 chars");

        let area = Rect::new(0, 0, 80, 2);
        let mut buf = Buffer::empty(area);
        msg.render_into(area, ThinkingDisplay::Collapsed, 5, &mut buf, &theme(), &est);

        let rendered = buf.content.iter().map(ratatui::buffer::Cell::symbol).collect::<String>();
        assert!(
            rendered.contains(&format!("({expected} tokens)")),
            "collapsed header should show the estimated token count. Got: {rendered}"
        );
        assert!(
            !rendered.contains("(8 tokens)"),
            "header must not use the word count. Got: {rendered}"
        );
    }

